<script lang="ts">
 import {Button,Select} from '@oshi-connect/ui';
 import ResetMark from './ResetMark.svelte';
 import {NO_MARKS,type ResetMarks} from '../editor/property-defaults';
 import type {SceneEntity,AvatarTracking,AvatarIdle} from '@opensekai/contracts';
 import {bodyPartOptions,bodyTrackingOf,sourceOptions,withBodyPart,withBodyTracking,withSource,type Commit,type SourceChannel,type SourceOption} from '../editor/live-fields';
 import {DEFAULT_AVATAR_BODY_TRACKING} from '@opensekai/contracts';
 import {SLIDERS} from '../editor/slider';
 import SliderField from './SliderField.svelte';
 let {marks=NO_MARKS,entityId,tracking,idleAnimation,onidle,entities,revision,disabled=false,oncommit,onguide}:{marks?:ResetMarks;entityId:string;tracking?:AvatarTracking;idleAnimation?:AvatarIdle;onidle?:Commit<AvatarIdle>;entities:SceneEntity[];revision:number;disabled?:boolean;oncommit?:Commit<AvatarTracking>;onguide?:(entityId:string)=>void}=$props();
 const body=$derived(sourceOptions(entities,'body',entityId)),face=$derived(sourceOptions(entities,'face',entityId)),fingers=$derived(sourceOptions(entities,'fingers',entityId));
 const bodyTracking=$derived(bodyTrackingOf(tracking));
 // The slider has no live edit: it keeps the last value of a drag and commits it on release.
 let slid:number|null=null;
 const intensity=(value:number)=>{void oncommit?.(entityId,withBodyTracking(tracking,{movementIntensity:value}),revision);};
 function change(channel:SourceChannel,value:string){void oncommit?.(entityId,withSource(tracking,channel,value),revision);}
 // The kit Select has no disabled option, so this marks the rendered options after each options change.
 const disableOptions=(options:SourceOption[])=>(node:HTMLElement)=>{for(const option of node.querySelectorAll('option'))option.disabled=options.find(item=>item.value===option.value)?.disabled??false;};
</script>
<div class="sources"><div class="resettable"><label class="idle-option"><input type="checkbox" checked={idleAnimation?.enabled??false} disabled={disabled||!onidle} onchange={event=>{void onidle?.(entityId,{kind:'builtin',enabled:event.currentTarget.checked},revision);}}/>Idle animation</label>{#if marks.changed.has('idleAnimation')}<ResetMark label="Idle animation" disabled={marks.disabled||disabled||!onidle} onreset={()=>{void onidle?.(entityId,{kind:'builtin',enabled:marks.defaults.idleAnimation===true},revision);}}/>{/if}</div><div {@attach disableOptions(body)}><Select label="Body source" value={tracking?.bodySourceId??''} options={body} disabled={disabled||!oncommit} onchange={event=>change('body',event.currentTarget.value)}/></div><div {@attach disableOptions(face)}><Select label="Face source" value={tracking?.faceSourceId??''} options={face} disabled={disabled||!oncommit} onchange={event=>change('face',event.currentTarget.value)}/></div><div {@attach disableOptions(fingers)}><Select label="Fingers source" value={tracking?.fingersSourceId??''} options={fingers} disabled={disabled||!oncommit} onchange={event=>change('fingers',event.currentTarget.value)}/></div><div class="resettable"><SliderField label="Body Movement Intensity" value={bodyTracking.movementIntensity} range={SLIDERS.bodyMovementIntensity} disabled={disabled||!oncommit} onlive={value=>{slid=value;}} onend={()=>{const value=slid;slid=null;if(value!==null)intensity(value);}} oncommit={intensity}/>{#if marks.changed.has('bodyMovementIntensity')}<ResetMark label="Body Movement Intensity" disabled={marks.disabled||disabled||!oncommit} onreset={()=>{void oncommit?.(entityId,withBodyTracking(tracking,{movementIntensity:DEFAULT_AVATAR_BODY_TRACKING.movementIntensity}),revision);}}/>{/if}</div><div class="resettable"><fieldset class="parts" disabled={disabled||!oncommit}><legend>Tracked Body Parts</legend>{#each bodyPartOptions as part (part.value)}<label class="idle-option"><input type="checkbox" checked={bodyTracking.trackedParts.includes(part.value)} onchange={async event=>{const box=event.currentTarget;await oncommit?.(entityId,withBodyPart(tracking,part.value,box.checked),revision);box.checked=bodyTracking.trackedParts.includes(part.value);}}/>{part.label}</label>{/each}</fieldset>{#if marks.changed.has('trackedParts')}<ResetMark label="Tracked Body Parts" disabled={marks.disabled||disabled||!oncommit} onreset={()=>{void oncommit?.(entityId,withBodyTracking(tracking,{trackedParts:[...DEFAULT_AVATAR_BODY_TRACKING.trackedParts]}),revision);}}/>{/if}</div><div><Button variant="secondary" disabled={disabled||!onguide} onclick={()=>onguide?.(entityId)}>Set up tracking</Button></div></div>
<style>.idle-option{display:flex;align-items:center;gap:7px;font-size:12px}.sources{display:grid;gap:10px}.parts{border:0;padding:0;margin:0;min-width:0;display:grid;grid-template-columns:1fr 1fr;gap:6px 10px}.parts legend{padding:0;margin-bottom:6px;font-size:12px;font-weight:600}</style>
